CREATE TABLE IF NOT EXISTS `folder_sources` (`localSourceId` TEXT NOT NULL, `encryptedTreeUri` TEXT NOT NULL, `scopeVersion` INTEGER NOT NULL, `state` TEXT NOT NULL, `scanGeneration` INTEGER NOT NULL, `lastAttemptAtEpochMs` INTEGER, `lastSuccessfulScanAtEpochMs` INTEGER, `observedCount` INTEGER NOT NULL, `eligibleCount` INTEGER NOT NULL, `excludedCount` INTEGER NOT NULL, `pendingCount` INTEGER NOT NULL, `lastErrorCode` TEXT, `serverSourceId` TEXT, `serverGeneration` INTEGER, `selectedAtEpochMs` INTEGER NOT NULL, PRIMARY KEY(`localSourceId`));
CREATE TABLE IF NOT EXISTS `folder_observations` (`observationId` TEXT NOT NULL, `localSourceId` TEXT NOT NULL, `documentIdHash` TEXT NOT NULL, `sha256` TEXT NOT NULL, `byteLength` INTEGER NOT NULL, `declaredMime` TEXT NOT NULL, `encryptedCopyName` TEXT NOT NULL, `providerSize` INTEGER, `providerModifiedAtEpochMs` INTEGER, `lastSeenGeneration` INTEGER NOT NULL, `state` TEXT NOT NULL, `observedAtEpochMs` INTEGER NOT NULL, `supersededBy` TEXT, PRIMARY KEY(`observationId`));
CREATE INDEX IF NOT EXISTS `index_folder_observations_localSourceId_documentIdHash_sha256` ON `folder_observations` (`localSourceId`, `documentIdHash`, `sha256`);
CREATE INDEX IF NOT EXISTS `index_folder_observations_localSourceId_lastSeenGeneration` ON `folder_observations` (`localSourceId`, `lastSeenGeneration`);
CREATE TABLE IF NOT EXISTS `folder_pending` (`localSourceId` TEXT NOT NULL, `documentIdHash` TEXT NOT NULL, `attempts` INTEGER NOT NULL, `providerSize` INTEGER, `providerModifiedAtEpochMs` INTEGER, PRIMARY KEY(`localSourceId`, `documentIdHash`));
